import {seed,validateEntries,verdict} from './core.js';
const $=s=>document.querySelector(s),key='replyshelf.v1';
let entries=structuredClone(seed),worker,busy=false,request=0,activeResults=[],lastReport,pendingImport,undoAction,toastTimer;
try{const saved=localStorage.getItem(key);if(saved!==null) entries=validateEntries(JSON.parse(saved));}catch(e){$('#notice').hidden=false;$('#notice').textContent='Your saved shelf could not be read. Samples are shown temporarily. Export anything important before saving changes.';}
function el(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
function toast(text,undo){clearTimeout(toastTimer);$('#toast span').textContent=text;$('#toast').hidden=false;$('#undo').hidden=!undo;undoAction=undo;toastTimer=setTimeout(()=>{$('#toast').hidden=true;undoAction=null;},10000);}
$('#undo').onclick=()=>{undoAction?.();$('#toast').hidden=true;undoAction=null;};
function save(next){try{localStorage.setItem(key,JSON.stringify(next));}catch{toast('Could not save. Storage may be full or disabled. Export a backup.');return false;}entries=next;request++;activeResults=[];$('#results').replaceChildren(el('p','Shelf updated. Search again to find an answer.','weak-text'));$('#result-count').textContent='—';renderLibrary();return true;}
function setBusy(value,message){busy=value;$('#find-button').disabled=value;$('#benchmark').disabled=value;document.querySelectorAll('[data-example]').forEach(b=>b.disabled=value);$('#engine-dot').classList.toggle('working',value);if(message)$('#engine-status').textContent=message;}
function ensureWorker(){if(worker)return;worker=new Worker('./engine.js',{type:'module'});worker.onmessage=({data})=>{
  if(data.type==='status'){$('#engine-status').textContent=data.message;return;}
  setBusy(false,'AI ready · running on your device');
  if(data.type==='result'&&data.request===request){activeResults=data.results;renderResult();$('#result-count').textContent=`${data.elapsed.toLocaleString()} ms`;}
  if(data.type==='benchmark'){lastReport=data;renderBenchmark(data);}
  if(data.type==='error'){setBusy(false,'Model unavailable — you can retry');toast('AI could not load. Check your connection and retry. Your shelf is still available.');$('#benchmark-results').textContent='Model could not load. Please check your connection and try again.';console.error(data.message);}
};worker.onerror=()=>{worker.terminate();worker=null;setBusy(false,'AI worker stopped — please retry');toast('AI could not start in this browser. Try a recent Chrome, Edge, or Firefox.');};}
function search(){const query=$('#query').value.trim();if(!query||busy)return;if(!entries.length){toast('Add an answer to your shelf first.');return;}ensureWorker();setBusy(true,'Finding the meaning of your question…');worker.postMessage({type:'search',query,entries:entries.map(({id,question})=>({id,question})),request:++request});}
$('#search-form').onsubmit=e=>{e.preventDefault();search();};$('#query').oninput=()=>{$('#char-count').textContent=`${$('#query').value.length} / 500`;};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.example;$('#query').oninput();search();});
$('#start-search').onclick=()=>{$('#workspace').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#query').focus({preventScroll:true});};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
document.querySelector('.brand').onclick=e=>{e.preventDefault();showView('find');};
function showView(view){document.querySelectorAll('.view').forEach(n=>n.hidden=n.id!==`${view}-view`);document.querySelectorAll('.nav').forEach(n=>{n.classList.toggle('active',n.dataset.view===view);n.setAttribute('aria-label',n.textContent.trim());n.setAttribute('aria-current',n.dataset.view===view?'page':'false');});window.scrollTo({top:0});}
function renderResult(selected=0){const holder=$('#results');holder.replaceChildren();if(!activeResults.length)return;const status=verdict(activeResults),hit=activeResults[selected],entry=entries.find(e=>e.id===hit.id);if(!entry)return;
  if(status==='weak'){holder.append(el('h2','This one needs a human.','weak-title'),el('p','No close answer found. Write a fresh reply, review it, then add it to your shelf for next time.','weak-text'),el('p',`Closest similarity: ${hit.score.toFixed(2)} · below the 0.42 review threshold.`,'review-note'));const add=el('button','+ Save a new answer','primary');add.onclick=()=>openEditor(null,$('#query').value);holder.append(add);return;}
  const meta=el('div',undefined,'match-meta');meta.append(el('span',entry.category.toUpperCase()),el('span',`Similarity ${hit.score.toFixed(2)}`));holder.append(meta,el('h2',entry.title,'result-title'));
  if(status==='ambiguous'||selected>0)holder.append(el('p',status==='ambiguous'?'Two answers are close. Compare the intent carefully before copying.':'You are reviewing an alternative match. Check that it answers the question.','match-warning'));
  holder.append(el('p',`Saved question: ${entry.question}`,'source-question'),el('div',entry.answer,'answer-text'));
  const copy=el('button','Copy this reply ↗','primary');copy.onclick=async()=>{try{await navigator.clipboard.writeText(entry.answer);toast('Copied. Review and personalize before sending.');}catch{toast('Clipboard unavailable. Select the reply text and copy it manually.');}};holder.append(copy,el('p','Exact saved text. Nothing is sent automatically. Similarity is not a correctness score.','review-note'));
  if(activeResults.length>1){const alternatives=el('div',undefined,'alternatives');alternatives.append(el('span','ALSO ON YOUR SHELF'));activeResults.slice(0,3).forEach((r,i)=>{if(i===selected)return;const other=entries.find(e=>e.id===r.id);const b=el('button',`${other.title}  ·  ${r.score.toFixed(2)}  ↗`);b.onclick=()=>renderResult(i);alternatives.append(b);});holder.append(alternatives);}
}
function renderLibrary(){const grid=$('#library-grid');grid.replaceChildren();$('#shelf-count').textContent=String(entries.length).padStart(2,'0');$('#entry-total').textContent=`${entries.length} / 100 saved answers`;$('#add-entry').disabled=entries.length>=100;
  const shelfNav=document.querySelector('.nav[data-view="library"]');shelfNav.setAttribute('aria-label',shelfNav.textContent.trim());
  entries.forEach(entry=>{const card=el('article',undefined,'shelf-card');card.append(el('span',entry.category,'category'),el('h2',entry.title),el('p',entry.question));const actions=el('div',undefined,'card-actions'),edit=el('button','Edit answer ↗'),del=el('button','Remove');edit.setAttribute('aria-label',`Edit ${entry.title}`);del.setAttribute('aria-label',`Remove ${entry.title}`);edit.onclick=()=>openEditor(entry);del.onclick=()=>{const previous=structuredClone(entries);if(save(entries.filter(e=>e.id!==entry.id)))toast('Answer removed.',()=>save(previous));};actions.append(edit,del);card.append(actions);grid.append(card);});
  if(!entries.length)grid.append(el('p','An empty shelf is a good beginning. Add your first answer.','weak-text'));
}
function openEditor(entry,question=''){if(!entry&&entries.length>=100){toast('This shelf is full. Remove an answer or export a backup.');return;}$('#editor-title').textContent=entry?'Edit your answer':'Add an answer';for(const field of ['id','title','category','question','answer'])$(`#entry-${field}`).value=entry?.[field]|| (field==='question'?question:'');$('#editor').showModal();}
$('#add-entry').onclick=()=>openEditor();$('#close-editor').onclick=()=>$('#editor').close();
$('#edit-form').onsubmit=e=>{e.preventDefault();const entry={};for(const f of ['id','title','category','question','answer'])entry[f]=$(`#entry-${f}`).value.trim();entry.id||=crypto.randomUUID();try{validateEntries([entry]);}catch(e){toast(e.message);return;}const next=entries.some(x=>x.id===entry.id)?entries.map(x=>x.id===entry.id?entry:x):[...entries,entry];if(save(next)){$('#editor').close();toast('Saved to your shelf.');}};
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>download('replyshelf-backup.json',{version:1,entries});$('#import').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>1024*1024){toast('Import files must be smaller than 1 MB.');return;}try{pendingImport=validateEntries(JSON.parse(await file.text()));$('#import-summary').textContent=`Import ${pendingImport.length} answers and replace your ${entries.length} current answers?`;$('#import-dialog').showModal();}catch(e){toast(`Could not import: ${e.message}`);}};
$('#cancel-import').onclick=()=>{pendingImport=null;$('#import-dialog').close();};$('#confirm-import').onclick=()=>{const previous=structuredClone(entries);if(pendingImport&&save(pendingImport)){pendingImport=null;$('#import-dialog').close();toast('Shelf imported.',()=>save(previous));}};
$('#benchmark').onclick=()=>{if(busy)return;ensureWorker();setBusy(true,'Running the comparison on your device…');$('#benchmark-results').textContent='Running the fixed sample set…';worker.postMessage({type:'benchmark'});};
function renderBenchmark(data){const holder=$('#benchmark-results');holder.replaceChildren();const semantic=data.rows.filter(r=>r.semantic===r.expected).length,lexical=data.rows.filter(r=>r.lexical===r.expected).length,unknown=data.unknown.filter(r=>r.verdict==='weak').length;const score=el('div',`${semantic} / 8`,'bench-score');score.append(el('small',`Semantic top-1 matches · word overlap ${lexical} / 8`));holder.append(score,el('p',`${unknown} / 3 unrelated questions withheld. ${data.elapsed.toLocaleString()} ms for the comparison, excluding model load. Cached repeats may be faster.`));const details=el('details'),summary=el('summary','Inspect every result');details.append(summary);const list=el('ul');data.rows.forEach(r=>list.append(el('li',`${r.query} → ${r.semantic} (${r.score.toFixed(2)}, ${r.verdict}); expected ${r.expected}. Word overlap: ${r.lexical}.`)));data.unknown.forEach(r=>list.append(el('li',`${r.query} → ${r.verdict} (${r.score.toFixed(2)})`)));details.append(list);holder.append(details,el('p','Synthetic examples written for this demo. Thresholds are heuristics; this is not a representative evaluation.'));$('#download-benchmark').hidden=false;}
$('#download-benchmark').onclick=()=>download('replyshelf-comparison.json',lastReport);
renderLibrary();showView('find');
